<script setup lang="ts">
import * as s from './state'
import { onMounted } from 'vue'
import ConnectionSettings from './components/ConnectionSettings.vue'
import TraceInspector from './components/TraceInspector.vue'
import ConversationSummaries from './components/ConversationSummaries.vue'
import ToolSettings from './components/ToolSettings.vue'
onMounted(() => s.session().catch((cause: any) => s.error.value = cause.message))
const promptKeys=[['persona','人设与语言风格'],['replyDecision','回复判断规则'],['groupReply','群聊接话风格'],['conversationSummary','阶段性总结与画像规则'],['memoryExtraction','记忆提取规则'],['vision','视觉理解'],['sticker','表情包选择']]
const labels:Record<string,string>={gallery:'图库',stickers:'表情包',memories:'记忆',people:'人物',chat:'消息'}
function json(v:any){return typeof v==='string'?v:JSON.stringify(v??'',null,2)}
function statusLabel(value:string|undefined){return ({online:'在线',offline:'离线',unconfirmed:'待验证','wrong-account':'账号不匹配','not-configured':'未配置',configured:'已配置','preview-only':'仅预览',running:'运行中',paused:'已暂停','waiting-connection':'等待连接'} as Record<string,string>)[value||'']||value||'未知'}
function onFile(e:Event){s.importFile(e)}
</script>
<template>
<div v-if="!s.authenticated.value" class="login"><section class="login-card"><div class="brand-mark">P</div><p class="eyebrow">LOCAL CONTROL CENTER</p><h1>宠物管理台</h1><p class="muted">使用管理员令牌登录本地控制面板</p><form @submit.prevent="s.login"><label>管理员令牌<input v-model="s.token.value" type="password" autocomplete="current-password" required placeholder="粘贴本地管理员令牌"></label><button class="primary wide">安全登录</button></form><p v-if="s.error.value" class="error">{{s.error.value}}</p></section></div>
<div v-else class="shell"><aside class="sidebar"><div class="brand"><div class="brand-mark">P</div><div><b>宠物管理台</b><small>LOCAL · PRIVATE</small></div></div><label class="pet-picker">当前宠物<select v-model="s.petId.value" @change="s.loadPet"><option v-for="p in s.pets.value" :key="p.id" :value="p.id">{{p.name}}</option></select></label><nav><button v-for="n in s.nav" :key="n[0]" :class="{active:s.page.value===n[0]}" @click="s.go(n[0])"><span>{{n[2]}}</span>{{n[1]}}</button></nav><div class="side-bottom"><span class="live-dot"></span>本地管理会话<button class="quiet" @click="s.logout">退出</button></div></aside>
<main class="main"><header class="topbar"><div><span class="crumb">工作空间 /</span> {{s.currentPet.value?.name||'宠物'}}</div><div class="top-right"><span class="sync">版本 {{s.pet.value?.version||'—'}}</span><button class="avatar">管</button></div></header><section class="content"><div v-if="s.error.value" class="alert">{{s.error.value}} <button @click="s.error.value=''">关闭</button></div><div v-if="s.notice.value" class="toast" @click="s.notice.value=''">{{s.notice.value}}　×</div><aside v-if="s.status.value?.live === false" class="preview-banner"><span class="preview-banner__icon">i</span><p><b>新版预览：QQ 接入尚未启用。</b> 这里保存的是新版数据，接入后生效；当前在线旧版不受这些修改影响。</p><button class="quiet" @click="s.go('settings')">查看接入设置 →</button></aside>
<template v-if="s.page.value==='overview'"><div class="page-head"><div><p class="eyebrow">OVERVIEW</p><h1>运行总览</h1><p class="muted">查看宠物运行状态与近期用量</p></div><button class="outline" @click="s.loadPage">刷新状态</button></div><div v-if="s.status.value" class="status-grid"><article class="metric"><span>QQ 登录</span><b>{{statusLabel(s.status.value.account?.state)}}</b><small>{{s.status.value.account?.accountId||'未提供账号'}}</small></article><article class="metric"><span>事件连接</span><b>{{statusLabel(s.status.value.connection?.state)}}</b><small>最近事件 {{s.status.value.connection?.lastEventAt||'暂无'}}</small></article><article class="metric"><span>工作进程</span><b>{{statusLabel(s.status.value.worker?.state)}}</b><small>队列积压 {{s.status.value.queue?.pending??'—'}}</small></article><article class="metric"><span>模型配置</span><b>{{s.status.value.model?.configured?'已配置':'未配置'}}</b><small>调用 {{s.status.value.usage?.calls??0}} 次</small></article><article class="metric"><span>输入 Token</span><b>{{s.status.value.usage?.promptTokens??0}}</b><small>缓存 {{s.status.value.usage?.cachedTokens??'—'}}</small></article><article class="metric"><span>输出 Token</span><b>{{s.status.value.usage?.completionTokens??0}}</b><small>单价未配置，暂无法计算金额</small></article></div><div v-else class="empty">暂无运行状态数据</div><section class="panel action-panel"><div><h3>运行控制</h3><p class="muted">操作会直接作用于当前宠物进程</p></div><div class="actions"><button class="outline" @click="s.control('pause')">暂停回复</button><button class="outline" @click="s.control('resume')">恢复回复</button><button class="outline" @click="s.control('reconnect')">重新连接</button></div></section><p class="footnote">扫码、验证与重启状态将在运行时提供后显示；页面不会推测在线状态。</p></template>
<template v-else-if="s.page.value==='prompt' && s.pet.value"><div class="page-head"><div><p class="eyebrow">PERSONA & PROMPTS</p><h1>Pet 与提示词</h1><p class="muted">分别维护角色提示词；保存后由运行时版本化。</p></div><button class="primary" @click="s.savePet">保存全部更改</button></div><div class="prompt-layout"><div class="panel prompt-panel"><label v-for="k in promptKeys" :key="k[0]" class="field"><span>{{k[1]}}</span><textarea v-model="s.pet.value.prompts[k[0]]" rows="5" :placeholder="'编辑'+k[1]+'…'"></textarea></label><div class="field"><span>运行设置</span><label class="check"><input type="checkbox" v-model="s.pet.value.settings.paused"> 暂停自动回复</label></div></div><aside class="panel preview-panel"><p class="eyebrow">LOCAL PREVIEW</p><h3>构造一条本地预览</h3><textarea v-model="s.preview.value" placeholder="输入一句话作为预览上下文" rows="3"></textarea><button class="outline wide" @click="s.previewPrompt">生成预览（不调用模型）</button><p class="muted tiny">本地预览不发送消息，也不写入正式记忆。</p><section v-if="s.previewResult.value" class="preview-result"><h4>构造的来源上下文</h4><p>版本 {{s.previewResult.value.promptVersion||'当前'}} · {{s.previewResult.value.messages?.length||0}} 条消息</p><article v-for="m in s.previewResult.value.messages||[]" :key="m.id" class="preview-source"><b>{{m.senderName||m.senderId||'来源'}}</b><time>{{m.sentAt||'时间未知'}}</time><p v-for="(part,i) in m.segments||[]" :key="i">{{part.text||`[${part.type}]`}}</p></article><h4>引用素材</h4><p v-for="(media,i) in s.previewResult.value.mediaSources||[]" :key="i">{{media.authorName||media.authorId||'作者未知'}} · {{media.sentAt||'时间未知'}} · {{media.relation||media.title||'素材'}}</p><h4>引用记忆</h4><p v-for="(memory,i) in s.previewResult.value.memories||[]" :key="i">{{memory.text||json(memory)}}</p><p v-if="!s.previewResult.value.mediaSources?.length&&!s.previewResult.value.memories?.length" class="muted tiny">此预览未选入素材或记忆。</p></section><hr><h3>模型测试</h3><textarea v-model="s.modelTest.value" rows="3" placeholder="测试输入（会产生一次模型调用）"></textarea><button class="outline wide" @click="s.testModel">测试模型 · 不执行外部动作</button><h3>提示词历史</h3><article v-for="r in s.revisions.value" :key="r.id" class="list-row"><div><b>{{r.createdAt||r.created_at||r.id}}</b><p>{{r.summary||r.actor||'历史版本'}}</p></div><button class="quiet" @click="s.restoreRevision(r)">恢复</button></article></aside></div></template>
<template v-else-if="['gallery','stickers','memories','people','chat'].includes(s.page.value)"><div class="page-head"><div><p class="eyebrow">PET LIBRARY</p><h1>{{labels[s.page.value]}}</h1><p class="muted">数据来自当前宠物管理接口 · 修改会保存到后端</p></div><div class="actions"><input v-if="s.page.value!=='chat'" v-model="s.search.value" class="search" placeholder="搜索标题、标签、说明…"><select v-if="['gallery','stickers'].includes(s.page.value)" v-model="s.categoryFilter.value" class="filter-select"><option value="">全部用途</option><option value="persona">人设素材</option><option value="drawing">作品</option><option value="reference">参考图</option><option value="sticker">表情包</option></select><select v-if="['gallery','stickers'].includes(s.page.value)" v-model="s.scopeFilter.value" class="filter-select"><option value="">全部范围</option><option value="public">公开</option><option value="private">私密</option></select><label v-if="['gallery','stickers'].includes(s.page.value)" class="primary upload">＋ 导入文件<input type="file" accept="image/*,video/*" @change="onFile"></label><button v-if="['memories','people'].includes(s.page.value)" class="primary" @click="s.openEdit()">＋ 新建</button><button class="outline" @click="s.loadPage">刷新</button></div></div><div v-if="s.page.value==='chat'" class="panel chat-list"><article v-for="m in s.filtered.value" :key="m.id" class="message"><div class="message-meta"><b>{{m.senderName||m.senderId||'未知发送者'}}</b><span>{{m.sentAt||'时间未知'}}</span><code>{{m.id}}</code></div><p v-for="(seg,i) in m.segments||[]" :key="i">{{seg.text||`[${seg.type}]`}}</p><small>会话 {{m.chatId}} · {{m.direction==='in'?'收到':'发出'}}<span v-if="m.replyTo"> · 回复 {{m.replyTo}}</span></small></article><div v-if="!s.filtered.value.length" class="empty">暂无消息记录</div><ConversationSummaries :items="s.summaries.value"/><TraceInspector :traces="s.traces.value"/></div><div v-else-if="['gallery','stickers'].includes(s.page.value)" class="asset-grid"><article v-for="a in s.filtered.value" :key="a.id" class="asset-card"><img v-if="a.mime?.startsWith('image/')||a.mimeType?.startsWith('image/')" :src="`/api/assets/${a.id}/media?petId=${s.petId.value}`" alt="素材预览"><div v-else class="asset-placeholder">▧</div><div class="asset-info"><b>{{a.title||a.file||a.id}}</b><p><b>{{a.kind==='sticker'?'表':'图'}}{{a.number}}</b> · {{a.category}} · {{a.scope}}</p><div class="tags">{{(a.tags||[]).join(' · ')}}</div><div class="actions"><button class="quiet" @click="s.openEdit(a)">编辑</button><button class="quiet" @click="s.hideRow(a)">{{a.hidden?'恢复':'隐藏'}}</button></div></div></article><div v-if="!s.filtered.value.length" class="empty">没有匹配内容</div></div><div v-else class="panel table-list"><article v-for="r in s.filtered.value" :key="r.id" class="list-row"><div><b>{{r.displayName||r.text||r.id}}</b><p>{{r.displayName?r.id:(r.scope||r.kind||'')}}</p><p v-if="r.fields">好感度 {{r.fields.affinity??10}} · {{r.fields.impression||r.fields.profile||'尚未形成画像'}}</p><small v-if="r.fields?.profileUpdatedAt">画像更新：{{new Date(r.fields.profileUpdatedAt).toLocaleString()}}</small><small v-if="r.lockedFields">锁定字段：{{r.lockedFields.join('、')||'无'}}</small></div><div class="actions"><button class="quiet" @click="s.openEdit(r)">编辑</button><button v-if="s.page.value==='memories'" class="quiet" @click="s.hideRow(r)">遗忘</button></div></article><div v-if="!s.filtered.value.length" class="empty">暂无数据</div></div></template>
<template v-else-if="s.page.value==='settings'"><div class="page-head"><div><p class="eyebrow">SETTINGS</p><h1>设置与备份</h1><p class="muted">备份操作由本地服务端执行</p></div><button class="primary" @click="s.backup">立即创建备份</button></div><section class="panel"><h3>回复行为</h3><p class="muted">配置保存在当前宠物中。</p><label class="setting-control"><input v-model="s.pet.value!.settings.proactiveReply" type="checkbox"><span><b>允许主动回复</b><small>开启后，宠物按回复判断规则参与对话。</small></span></label><label class="field setting-field"><span>回复判断间隔（毫秒）</span><input v-model.number="s.pet.value!.settings.decisionIntervalMs" type="number" min="1000" step="1000"></label><label class="field setting-field"><span>主动回复冷却（毫秒）</span><input v-model.number="s.pet.value!.settings.proactiveCooldownMs" type="number" min="0" step="5000"></label><label class="setting-control"><input v-model="s.pet.value!.settings.profileSummaryEnabled" type="checkbox"><span><b>阶段性总结并更新画像</b><small>按 QQ 号记录来源，尊重已锁定的画像字段。</small></span></label><label class="field setting-field"><span>每批消息数</span><input v-model.number="s.pet.value!.settings.profileSummaryMessageCount" type="number" min="8" max="100"></label><label class="field setting-field"><span>会话安静后总结（分钟）</span><input v-model.number="s.pet.value!.settings.profileSummaryIdleMinutes" type="number" min="2" max="120"></label><button class="primary" @click="s.savePet">保存回复与总结设置</button></section><section class="panel"><h3>当前宠物状态</h3><div class="setting-line"><span>回复暂停</span><b>{{s.pet.value?.settings?.paused?'已暂停':'未暂停'}}</b></div><div class="setting-line"><span>配置版本</span><b>{{s.pet.value?.version}}</b></div></section><ToolSettings v-if="s.pet.value" :settings="s.pet.value.settings" @save="s.saveTools"/><ConnectionSettings :value="s.connection.value" @save="s.saveConnection"/><section class="panel backups"><h3>备份记录</h3><article v-for="b in s.backups.value" :key="b.id" class="list-row"><div><b>{{b.id}}</b><p>{{b.createdAt||b.created_at||'时间未提供'}} · {{b.status||'可用'}}</p></div><button class="outline" @click="s.restore(b)">恢复</button></article><div v-if="!s.backups.value.length" class="empty">暂无备份记录</div></section></template>
</section></main>
<div v-if="s.selected.value" class="veil" @click.self="s.selected.value=null"><section class="dialog"><header><h2>{{s.selected.value.id?'编辑':'新建'}}{{labels[s.page.value]||'素材'}}</h2><button class="quiet" @click="s.selected.value=null">×</button></header><label v-for="(v,k) in Object.fromEntries(Object.entries(s.form.value).filter(([key])=>key!=='base64'))" :key="k" class="field"><span>{{k}}</span><textarea v-if="typeof v==='object'" :value="json(v)" @input="e=>{try{s.form.value[k]=JSON.parse((e.target as HTMLTextAreaElement).value)}catch{s.form.value[k]=(e.target as HTMLTextAreaElement).value}}" rows="3"></textarea><textarea v-else-if="String(v).length>70" v-model="s.form.value[k]" rows="4"></textarea><input v-else v-model="s.form.value[k]" type="text"></label><footer><button class="outline" @click="s.selected.value=null">取消</button><button class="primary" @click="s.saveRow">保存更改</button></footer></section></div>
</div>
</template>
